'use strict';
const $=id=>document.getElementById(id), $$=s=>[...document.querySelectorAll(s)], D=Array.from({length:10},(_,i)=>i);
const fresh=()=>({mode:'straight',positions:[[...D],[...D],[...D]],pool:[...D],sumMin:0,sumMax:27,spanMin:0,spanMax:9,odd:'',big:'',shape:'',route:'',include:[],exclude:[]});
let game='fc3d',f=fresh(),candidates=[],sample=[],resultMode='all',page=0,timer;
const names={fc3d:'福彩 3D',pl3:'体彩排列三'},modes={straight:'单选 / 直选',g3:'组选三',g6:'组选六'},pageSize=24;
function read(key,fallback){try{return JSON.parse(localStorage.getItem('numberlab-'+key))??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem('numberlab-'+key,JSON.stringify(value));return true;}catch{toast('浏览器存储不可用，数据未保存；请导出备份。');return false;}}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function coverage(n){return n*(f.mode==='g3'?3:f.mode==='g6'?6:1)/10;}
function view(v){$$('.view').forEach(x=>x.hidden=x.id!==v);$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const title={workbench:'选号工作台',history:'历史统计',learn:'技巧资料库',saved:'我的方案'}[v];$('page-name').textContent=title;$('heading').textContent={workbench:'把选号思路，变成清晰的组合。',history:'让历史数据，回到事实本身。',learn:'理解方法，也理解它的边界。',saved:'留住思路，方便下次研究。'}[v];$('subtitle').textContent={workbench:'从条件筛选到组合生成，让每一个号码都有迹可循。',history:'分别导入两个彩种的数据，观察频次、遗漏与号码形态。',learn:'玩法有规则，筛选有依据，随机结果没有必中公式。',saved:'按彩种管理你的方案，随时查看、还原或导出。'}[v];if(v==='history')renderHistory();if(v==='saved')renderSaved();}
$$('nav button').forEach(x=>x.onclick=()=>view(x.dataset.view));$$('[data-goto]').forEach(x=>x.onclick=()=>view(x.dataset.goto));$('help').onclick=()=>view('learn');
$$('[data-game]').forEach(x=>x.onclick=()=>{if(game===x.dataset.game)return;game=x.dataset.game;$$('[data-game]').forEach(b=>b.classList.toggle('active',b===x));$$('.game-name').forEach(e=>e.textContent=names[game]);$('history-input').value='';$('history-error').textContent='';f=fresh();sync();recompute();renderHistory();renderSaved();toast('已切换至'+names[game]);});
function renderDigits(){const isStraight=f.mode==='straight';$('pool-label').textContent=isStraight?'定位选号':'组选号码池';$('mode-hint').textContent=isStraight?'百、十、个位分别筛选，保留所有有序组合。':'不区分位置，升序展示并去重；重复数字的个数保持不变。';$('shape').disabled=!isStraight;const rows=isStraight?['百位','十位','个位']:['号码池'];$('digit-selectors').innerHTML=rows.map((label,i)=>`<div class="digit-row"><div class="digit-row-head"><span>${label}</span><div><button data-all="${i}">全选</button><button data-none="${i}">清空</button></div></div><div class="digits">${D.map(n=>`<button class="${(isStraight?f.positions[i]:f.pool).includes(n)?'selected':''}" aria-label="${label}数字${n}" aria-pressed="${(isStraight?f.positions[i]:f.pool).includes(n)}" data-row="${i}" data-digit="${n}">${n}</button>`).join('')}</div></div>`).join('');$$('[data-digit]').forEach(b=>b.onclick=()=>{const a=isStraight?f.positions[+b.dataset.row]:f.pool,n=+b.dataset.digit;const i=a.indexOf(n);i<0?a.push(n):a.splice(i,1);renderDigits();recompute();});for(const kind of ['all','none'])$$('[data-'+kind+']').forEach(b=>b.onclick=()=>{const a=kind==='all'?[...D]:[];isStraight?f.positions[+b.dataset[kind]]=a:f.pool=a;renderDigits();recompute();});}
function sync(){for(const key of ['mode','sumMin','sumMax','spanMin','spanMax','odd','big','shape','route'])$(key).value=f[key];$('include').value=f.include.join(' ');$('exclude').value=f.exclude.join(' ');renderDigits();}
function validate(){for(const [a,b,max,label] of [['sumMin','sumMax',27,'和值'],['spanMin','spanMax',9,'跨度']]){if([a,b].some(k=>$(k).value.trim()===''||!Number.isInteger(Number($(k).value))||+$(k).value<0||+$(k).value>max))throw Error(label+'必须是 0–'+max+' 之间的整数。');if(+$(a).value>+$(b).value)throw Error(label+'下限不能大于上限。');f[a]=+$(a).value;f[b]=+$(b).value;}for(const k of ['include','exclude']){if(!/^[\d\s,，]*$/.test($(k).value))throw Error('必含与排除仅接受 0–9 数字及空格、逗号。');f[k]=[...new Set(($(k).value.match(/\d/g)||[]).map(Number))];}if(f.include.some(n=>f.exclude.includes(n)))throw Error('同一数字同时设置为必含和排除，请调整条件。');}
function recompute(){sample=[];page=0;resultMode='all';$('filter-error').textContent='';try{validate();candidates=Lottery.filter(f);}catch(e){candidates=[];$('filter-error').textContent=e.message;}$('candidate-count').innerHTML=candidates.length.toLocaleString()+'<small>组</small>';$('coverage').innerHTML=coverage(candidates.length).toFixed(1).replace('.0','')+'<small>%</small>';$('cost').innerHTML=(candidates.length*2).toLocaleString()+'<small>元</small>';const total=f.mode==='g3'?90:f.mode==='g6'?120:1000;$('removed').textContent=candidates.length===total?'全部组合均保留':'已过滤 '+(total-candidates.length)+' / '+total+' 组';const bins=Array(28).fill(0);candidates.forEach(c=>bins[c.sum]++);const max=Math.max(...bins,1);$('histogram').innerHTML=bins.map((n,i)=>`<div class="bar" title="和值 ${i}：${n} 个组合" style="height:${n/max*100}%"></div>`).join('');$('histogram').setAttribute('aria-label','和值分布：'+bins.map((n,i)=>i+'点'+n+'组').join('，'));renderNumbers();}
for(const k of ['mode','odd','big','shape','route'])$(k).onchange=()=>{f[k]=$(k).value;if(k==='mode'){f.shape='';$('shape').value='';renderDigits();}recompute();};for(const k of ['sumMin','sumMax','spanMin','spanMax','include','exclude'])$(k).oninput=recompute;
$('reset').onclick=()=>{f=fresh();sync();recompute();};
function renderNumbers(){const rows=resultMode==='all'?candidates:sample;$$('[data-result]').forEach(b=>b.classList.toggle('active',b.dataset.result===resultMode));$('result-label').textContent=rows.length;$('result-desc').textContent=resultMode==='all'?'完整候选集，按号码升序排列':'候选集中等概率、不重复抽取；不构成号码推荐';$('numbers').innerHTML=rows.length?rows.slice(page*pageSize,(page+1)*pageSize).map(x=>`<div class="number-cell">${x.n}<small>和 ${x.sum} · 跨 ${x.span}</small></div>`).join(''):`<div class="empty"><strong>${resultMode==='sample'?'还没有随机方案':'没有符合条件的组合'}</strong>${resultMode==='sample'?'设置抽取组数，点击“随机生成”。':'放宽和值、跨度或号码限制，试试更多组合。'}</div>`;$('page-info').textContent=rows.length?`第 ${page+1} / ${Math.ceil(rows.length/pageSize)} 页 · 共 ${rows.length} 组`:'0 组';$('prev').disabled=page===0;$('next').disabled=(page+1)*pageSize>=rows.length;$('export').disabled=!rows.length;$('random').disabled=!candidates.length;$('save').disabled=!sample.length;$('plan-cost').textContent=sample.length?`随机方案 ${sample.length} 注 · 单倍 ${sample.length*2} 元 · 理论覆盖 ${coverage(sample.length).toFixed(1)}%`:'先生成一个随机方案';$('plan-coverage').textContent=sample.length?'此处覆盖仅指当前随机方案，对应公平等可能开奖假设。':'在候选集中不重复抽取；不对号码进行胜率排序。';}
$$('[data-result]').forEach(b=>b.onclick=()=>{resultMode=b.dataset.result;page=0;renderNumbers();});$('prev').onclick=()=>{page--;renderNumbers();};$('next').onclick=()=>{page++;renderNumbers();};$('random').onclick=()=>{const n=+$('sample-size').value;if(!Number.isInteger(n)||n<1||n>1000){toast('抽取组数应为 1–1000 的整数。');return;}sample=Lottery.sample(candidates,Math.min(n,candidates.length));resultMode='sample';page=0;renderNumbers();if(n>candidates.length)toast('候选数量不足，已取全部 '+candidates.length+' 组。');};
function download(name,text){const blob=new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRows(rows,mode=f.mode){download(names[game]+'-'+modes[mode]+'-号码.csv','彩种,玩法,号码,和值,跨度,奇数个数,大数个数,012路\r\n'+rows.map(x=>[names[game],modes[mode],'="'+x.n+'"',x.sum,x.span,x.odd,x.big,'="'+x.routes+'"'].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'));toast('已导出 '+rows.length+' 组号码');}
$('export').onclick=()=>exportRows(resultMode==='all'?candidates:sample);
function saved(){const a=read('saved-'+game,[]);return Array.isArray(a)?a:[];}
$('save').onclick=()=>{const a=saved();if(a.length>=100){toast('最多保存 100 个方案，请先删除不需要的方案。');return;}a.unshift({id:crypto.randomUUID(),created:new Date().toISOString(),filter:JSON.parse(JSON.stringify(f)),numbers:sample.map(x=>x.n)});if(write('saved-'+game,a)){toast('方案已保存至“我的方案”');renderSaved();}};
function renderSaved(){const a=saved();$('saved-count').textContent=a.length;$('saved-list').innerHTML=a.length?a.map((s,i)=>`<article class="saved-item"><div><strong>${modes[s.filter.mode]} · ${s.numbers.length} 组</strong><p>${new Date(s.created).toLocaleString('zh-CN')} · 单倍 ${s.numbers.length*2} 元</p><div class="saved-numbers">${s.numbers.slice(0,18).join(' · ')}${s.numbers.length>18?' …':''}</div><p>和值 ${s.filter.sumMin}–${s.filter.sumMax} · 跨度 ${s.filter.spanMin}–${s.filter.spanMax}</p></div><div class="button-row"><button class="outline" data-restore="${i}">还原</button><button class="text-button" data-download="${i}">导出</button><button class="text-button" data-delete="${i}">删除</button></div></article>`).join(''):'<div class="empty"><strong>这里等待你的第一个方案</strong>在选号工作台生成随机方案后，点击“保存方案”。</div>';$$('[data-restore]').forEach(b=>b.onclick=()=>{const s=a[+b.dataset.restore];f=JSON.parse(JSON.stringify(s.filter));sync();recompute();sample=s.numbers.map(Lottery.describe);resultMode='sample';page=0;renderNumbers();view('workbench');toast('已还原条件与号码');});$$('[data-download]').forEach(b=>b.onclick=()=>{const s=a[+b.dataset.download];exportRows(s.numbers.map(Lottery.describe),s.filter.mode);});$$('[data-delete]').forEach(b=>b.onclick=()=>{a.splice(+b.dataset.delete,1);if(write('saved-'+game,a))renderSaved();});}
function renderHistory(){const rows=read('history-'+game,[]);$('history-size').textContent=rows.length?rows.length+' 期 · 用户导入':'未导入数据';if(!rows.length){$('frequency').innerHTML='<div class="empty"><strong>用你的数据，开始一次观察</strong>导入后显示数字 0–9 的频次和当前遗漏。</div>';$('history-table').innerHTML='<div class="empty">暂无历史数据；本工具不内置示例开奖。</div>';$('clear-history').disabled=true;return;}$('clear-history').disabled=false;const stats=Lottery.stats(rows),max=Math.max(...stats.map(s=>s.count),1);$('frequency').innerHTML='<div class="frequency-row"><span>数字</span><span>出现次数（含重复位）</span><span>次数</span><span>遗漏期数</span></div>'+stats.map(s=>`<div class="frequency-row"><b>${s.digit}</b><div class="frequency-track"><span style="width:${s.count/max*100}%"></span></div><span>${s.count}</span><span>${s.unseen?'≥ ':''}${s.omission} 期</span></div>`).join('');$('history-table').innerHTML='<table><thead><tr><th>期号</th><th>号码</th><th>和值</th><th>跨度</th><th>奇 : 偶</th><th>大 : 小</th><th>012 路</th></tr></thead><tbody>'+rows.slice(-50).reverse().map(r=>`<tr><td>${r.issue}</td><td class="num">${r.n}</td><td>${r.sum}</td><td>${r.span}</td><td>${r.odd} : ${3-r.odd}</td><td>${r.big} : ${3-r.big}</td><td>${r.routes}</td></tr>`).join('')+'</tbody></table>';}
$('import-history').onclick=()=>{try{const rows=Lottery.parseHistory($('history-input').value);if(write('history-'+game,rows)){renderHistory();$('history-error').textContent='';toast('已导入 '+rows.length+' 期，请确保输入顺序从旧到新。');}}catch(e){$('history-error').textContent=e.message;}};$('history-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){$('history-error').textContent='文件不能超过 2 MB。';e.target.value='';return;}$('history-input').value=await file.text();$('history-error').textContent='文件已读取，请核对顺序后点击“导入并分析”。';e.target.value='';};$('template').onclick=()=>download('历史导入格式模板.csv','期号,号码\r\n');$('clear-history').onclick=()=>{if(write('history-'+game,[])){renderHistory();$('history-input').value='';toast('已清除当前彩种历史数据');}};
const lessons=[
['和值筛选','将三个数字相加，得到 0–27 的和值。用区间表达你的选择偏好，并实时观察减少了多少组合。','1 + 4 + 8 = 13','中间和值对应更多组合；每个具体的有序号码仍为 1/1000。','sum'],
['跨度筛选','最大数字减去最小数字，得到 0–9 的跨度。跨度反映三个数字的分散程度。','148 → 8 − 1 = 7','跨度是分类条件，不是下一期开奖方向。','span'],
['奇偶与大小','奇数为 1、3、5、7、9；偶数包含 0。大小以 5 为界，0–4 为小，5–9 为大。','148 → 1 奇 2 偶 · 1 大 2 小','“看起来均衡”的号码，并不比其他具体号码更容易中出。','odd'],
['012 路分类','按数字除以 3 的余数分类：0 路为 0、3、6、9；1 路为 1、4、7；2 路为 2、5、8。','148 → 1、1、2 路','三类数字数量不同，不能把三路当作等概率事件。此处按无序路组合筛选。','route'],
['单选与组选','单选 / 直选匹配顺序；组选三含一个对子，组选六的三个数字各不相同。组选不区分顺序。','112 → 3 种排列 · 123 → 6 种排列','单注理论覆盖分别为 0.1%、0.3%、0.6%，不同玩法的奖金也不同。','groups'],
['冷热与遗漏','冷热描述给定样本中的频次；遗漏描述连续未出现期数。可以用导入的数据观察这两个指标。','历史统计 ≠ 未来预测','独立开奖假设下，“很久没出”不意味着下一期更容易出现。重复购买同一号码也不增加单期覆盖。','history']];
$('lessons').innerHTML=lessons.map((l,i)=>`<article class="card lesson"><span class="lesson-no">0${i+1}</span><h3>${l[0]}</h3><p>${l[1]}</p><div class="example">${l[2]}</div><p class="boundary">${l[3]}</p><button data-preset="${l[4]}">${l[4]==='history'?'前往历史统计':'在工作台试一试'} →</button></article>`).join('');
$$('[data-preset]').forEach(b=>b.onclick=()=>{const p=b.dataset.preset;if(p==='history'){view('history');return;}f=fresh();if(p==='sum'){f.sumMin=10;f.sumMax=18;}if(p==='span'){f.spanMin=3;f.spanMax=7;}if(p==='odd')f.odd='1';if(p==='route')f.route='012';if(p==='groups')f.mode='g6';sync();recompute();view('workbench');toast('已应用演示条件，可自由调整；这不是预测推荐。');});
sync();recompute();renderSaved();
